#!/usr/bin/env python3
"""MOAI-CPU m7 softmax phase split: the softmax's own bootstrap (bootstrapper_att.bootstrap_3) broke
when the main phase split removed the full gal_keys_boot. Port of palma's phased softmax bootstrap:
boot keys in 3 phases from the same ./phase_keys files; public Bootstrapper sub-transforms, no fork class.
    patch_softmax_phase.py <moai source root>
"""
import os, sys
SRC = 'include/source/non_linear_func/softmax.hpp'
ANCHOR_INJ = 'using namespace seal;\n\nCiphertext exp('
INJ_TO = 'using namespace seal;\n\n\n// ===== SNNI m7 softmax phase_split (ported from palma_campaign; reuses main phase keys; glibc/our fork) =====\n#include <fstream>\n#include <malloc.h>\n#include <stdexcept>\nstatic void cleanup_softmax_log_rss(const string &) {}\nstatic string get_softmax_work_dir() {\n    const char *v = getenv("MOAI_WORK_DIR");\n    return v ? string(v) : string(".");\n}\nstatic const string stage_softmax_key_dir = get_softmax_work_dir() + "/phase_keys";\n// ADAPTED: drop palma\'s MemoryPoolHandle::New(true) scope -> load under our global threshold pool\n// (same approach as the main stage_load_boot_phase). Reuses the 3 phase-key files the main port saved.\nstatic void stage_softmax_load_boot_phase(int phase, Bootstrapper &bootstrapper) {\n  bootstrapper.gal_keys = GaloisKeys();\n  malloc_trim(0);\n  string path = stage_softmax_key_dir + "/boot_phase_" + to_string(phase) + ".keys";\n  ifstream in(path, ios::binary);\n  if (!in) { throw runtime_error("failed to open softmax boot phase key input: " + path); }\n  bootstrapper.gal_keys.load(bootstrapper.context, in);\n  malloc_trim(0);\n}\nstatic void stage_softmax_bootstrap_split(Bootstrapper &bs, Ciphertext &rtncipher, Ciphertext &cipher) {\n  double input_initial_scale = cipher.scale();\n  const auto &modulus = iter(bs.context.first_context_data()->parms().coeff_modulus());\n  bs.modraise_inplace(cipher);\n  cipher.scale() = (double)modulus[0].value();\n  cleanup_softmax_log_rss("softmax_split_modraise_done");\n\n  int logn = bs.logn;\n  int dp1 = (int)floor(logn / 3.0);\n  int dp2 = (int)floor((logn - dp1) / 2.0);\n  int dp3 = logn - dp1 - dp2;\n  int tl1 = (1 << dp1) - 1;\n  int tl2 = (1 << dp2) - 1;\n  int tl3 = (1 << dp3) - 1;\n  int bs1_inv = 1 << (logn - dp1);\n  int bs2_inv = 1 << (logn - dp1 - dp2);\n  int bs3_inv = 1;\n\n  int dp3f = (int)floor(logn / 3.0);\n  int dp2f = (int)floor((logn - dp3f) / 2.0);\n  int dp1f = logn - dp3f - dp2f;\n  int tl1f = (1 << dp1f) - 1;\n  int tl2f = (1 << dp2f) - 1;\n  int tl3f = (1 << dp3f) - 1;\n  int bs1_fwd = 1;\n  int bs2_fwd = 1 << dp1f;\n  int bs3_fwd = 1 << (dp1f + dp2f);\n\n  stage_softmax_load_boot_phase(0, bs);\n  Ciphertext cts1;\n  bs.rotated_bsgs_linear_transform(cts1, cipher, tl1, bs1_inv, logn, bs.invfftcoeff1[bs.slot_index]);\n  bs.evaluator.rescale_to_next_inplace(cts1);\n  cipher = Ciphertext();\n  cleanup_softmax_log_rss("softmax_split_cts1_done");\n\n  stage_softmax_load_boot_phase(1, bs);\n  Ciphertext cts2;\n  bs.bsgs_linear_transform(cts2, cts1, tl2, bs2_inv, logn, bs.invfftcoeff2[bs.slot_index]);\n  bs.evaluator.rescale_to_next_inplace(cts2);\n  cts1 = Ciphertext();\n  cleanup_softmax_log_rss("softmax_split_cts2_done");\n\n  stage_softmax_load_boot_phase(2, bs);\n  Ciphertext cts3;\n  bs.bsgs_linear_transform(cts3, cts2, tl3, bs3_inv, logn + 1, bs.invfftcoeff3[bs.slot_index]);\n  bs.evaluator.rescale_to_next_inplace(cts3);\n  cts2 = Ciphertext();\n  Ciphertext conj;\n  bs.evaluator.complex_conjugate(cts3, bs.gal_keys, conj);\n  bs.evaluator.add_inplace_reduced_error(cts3, conj);\n  cleanup_softmax_log_rss("softmax_split_cts3_done");\n\n  Ciphertext modrtn;\n  bs.mod_reducer->modular_reduction(modrtn, cts3);\n  cts3 = Ciphertext();\n  cleanup_softmax_log_rss("softmax_split_modred_done");\n\n  Ciphertext stc1;\n  bs.bsgs_linear_transform(stc1, modrtn, tl1f, bs1_fwd, logn, bs.fftcoeff1[bs.slot_index]);\n  bs.evaluator.rescale_to_next_inplace(stc1);\n  modrtn = Ciphertext();\n  cleanup_softmax_log_rss("softmax_split_stc1_done");\n\n  stage_softmax_load_boot_phase(1, bs);\n  Ciphertext stc2;\n  bs.bsgs_linear_transform(stc2, stc1, tl2f, bs2_fwd, logn, bs.fftcoeff2[bs.slot_index]);\n  bs.evaluator.rescale_to_next_inplace(stc2);\n  stc1 = Ciphertext();\n  cleanup_softmax_log_rss("softmax_split_stc2_done");\n\n  stage_softmax_load_boot_phase(0, bs);\n  auto chain_index = bs.context.get_context_data(stc2.parms_id())->chain_index();\n  double mod_zero = (double)modulus[0].value();\n  double curr_mod = (double)modulus[chain_index].value();\n  vector<vector<complex<double>>> fftcoeff3_scale(tl3f + 1);\n  for (int a = 0; a < tl3f + 1; a++) {\n    fftcoeff3_scale[a].resize(bs.n);\n    for (int b = 0; b < bs.n; b++) {\n      fftcoeff3_scale[a][b] = bs.fftcoeff3[bs.slot_index][a][b]\n        * curr_mod * mod_zero * bs.final_scale\n        / (stc2.scale() * stc2.scale() * input_initial_scale);\n    }\n  }\n  bs.rotated_bsgs_linear_transform(rtncipher, stc2, tl3f, bs3_fwd, logn, fftcoeff3_scale);\n  bs.evaluator.rescale_to_next_inplace(rtncipher);\n  rtncipher.scale() = bs.final_scale;\n  stc2 = Ciphertext();\n  cleanup_softmax_log_rss("softmax_split_stc3_done");\n}\n// ===== end SNNI m7 softmax phase_split =====\n\n\nCiphertext exp('
ANCHOR_CALL = '  bootstrapper_att.bootstrap_3(rtn,sum_exp_x);\n'
CALL_TO = '  stage_softmax_bootstrap_split(bootstrapper_att, rtn, sum_exp_x);\n'
def main():
    if len(sys.argv) != 2: sys.exit(__doc__)
    p = os.path.join(sys.argv[1], SRC)
    if not os.path.exists(p): sys.exit("FAILED: no " + SRC)
    t = open(p).read()
    if "stage_softmax_bootstrap_split" in t: sys.exit("FAILED: softmax phase already applied")
    if t.count(ANCHOR_INJ) != 1: sys.exit(f"FAILED: INJ anchor {t.count(ANCHOR_INJ)}")
    if t.count(ANCHOR_CALL) != 1: sys.exit(f"FAILED: CALL anchor {t.count(ANCHOR_CALL)}")
    t = t.replace(ANCHOR_INJ, INJ_TO, 1).replace(ANCHOR_CALL, CALL_TO, 1)
    open(p, "w").write(t)
    o = open(p).read()
    for w in ("stage_softmax_load_boot_phase","stage_softmax_bootstrap_split(bootstrapper_att","stage_softmax_key_dir"):
        if w not in o: sys.exit(f"FAILED: {w!r} absent after patch")
    if "bootstrapper_att.bootstrap_3(" in o: sys.exit("FAILED: monolithic softmax bootstrap_3 remains")
    if "MemoryPoolThresholdMT" in o: sys.exit("FAILED: MemoryPoolThresholdMT present (missing in fork)")
    print("patch_softmax_phase: softmax bootstrap phase-split applied (" + SRC + ")")
if __name__ == "__main__": main()
